import { lagosDayStart, lagosHour } from './format';
import { OYO as dep } from './deployments/oyo';
import { DAY, HOUR, MIN } from './platform/engine';
import type { CategoryId, Channel, Identity, Incident, Shift } from './platform/types';
import type { DutyEntry, ReportInput, SeedApi } from './store';

// Seven days of history, generated by running the real actions at past
// times, so every dashboard number is backed by case records and audit.

function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const R = rng(20261016);
const pick = <T,>(xs: T[]) => xs[Math.floor(R() * xs.length)];
const between = (a: number, b: number) => a + R() * (b - a);
function weighted<T extends string>(w: Record<T, number>): T {
  const total = Object.values<number>(w).reduce((a, b) => a + b, 0);
  let x = R() * total;
  for (const [k, v] of Object.entries<number>(w)) {
    x -= v;
    if (x <= 0) return k as T;
  }
  return Object.keys(w)[0] as T;
}

const T: Record<string, string[]> = {
  'security/armed': ['Two men with guns seen around {a}, moving towards the junction', 'Gunshots heard near {a} market just now', 'Awon eniyan kan gbe ibon ni {a}', 'Some boys with cutlass dey threaten people for {a} junction'],
  'security/robbery': ['Robbers broke into a shop at {a}, happening now', 'Armed robbery on the road to {a}, they are collecting phones', 'Ole ti wo ile kan ni {a}'],
  'security/kidnapping': ['A man was abducted near {a} this evening, they took him in a white car', 'Kidnappers seen around the farm road in {a}'],
  'security/violence': ['Cult clash at {a}, boys are fighting with machetes', 'Serious fight between two groups at {a} motor park'],
  'security/suspicious': ['Strange men loitering around {a} school late at night', 'Suspicious vehicle parked near {a} for 3 days, men watching houses', 'Unknown men dey waka around {a} since evening'],
  'security/threat': ['Area boys are extorting traders at {a} market and threaten anyone who refuses'],
  'security/gbv': ['My neighbour beats his wife every night at {a}, she was bleeding today', 'A girl was sexually abused in {a}, the family is afraid to report'],
  'security/tip': ['I know where the people who robbed shops in {a} stay, they meet at an uncompleted building'],
  'fire/building': ['Fire at a shop in {a} market, smoke everywhere', 'Ina n jo ni {a}'],
  'fire/electrical': ['Transformer on fire at {a}'],
  'fire/vehicle': ['Tanker on fire near {a}'],
  'fire/bush': ['Bush burning close to houses in {a}'],
  'flooding/flood': ['Flooding at {a}, water has entered houses', 'The whole street in {a} is submerged after the rain', 'Ikun omi ti bo ona ni {a}'],
  'flooding/drainage': ['Drainage at {a} is blocked and overflowing onto the road', 'The gutter by {a} junction is full of refuse and overflowing'],
  'roads/state_road': ['Big potholes on the expressway near {a}, cars are swerving', 'The highway section at {a} has collapsed'],
  'roads/local_road': ['The road to {a} has completely collapsed', 'Potholes everywhere on our street in {a}', 'Ona {a} ti baje patapata'],
  'roads/bridge': ['The culvert bridge at {a} is cracking'],
  'waste/refuse': ['Refuse has not been collected in {a} for two weeks, the smell is terrible', 'Panti ti po ju ni {a}'],
  'waste/dumping': ['People are dumping refuse illegally at the {a} roundabout'],
  'infrastructure/electrical': ['Live wire hanging low at {a} after the storm', 'Fallen electric pole at {a} junction'],
  'infrastructure/streetlight': ['Streetlight not working along {a} road'],
  'infrastructure/water': ['Burst pipe at {a}, water wasting since morning'],
  'infrastructure/facility': ['The health centre building in {a} is abandoned and the roof is falling'],
};

const SUBS: Record<Exclude<CategoryId, 'other'>, Record<string, number>> = {
  security: { armed: 14, robbery: 16, kidnapping: 5, violence: 14, suspicious: 26, threat: 10, gbv: 8, tip: 4, sos: 6 },
  fire: { building: 55, electrical: 20, vehicle: 10, bush: 15 },
  flooding: { flood: 45, drainage: 55 },
  roads: { state_road: 30, local_road: 60, bridge: 10 },
  waste: { refuse: 75, dumping: 25 },
  infrastructure: { electrical: 35, streetlight: 30, water: 20, facility: 15 },
};

// How quickly each responder really works (1 = on target, higher = slower).
const PACE: Record<string, number> = { waste: 1.7, rma: 2.4, drain: 1.1, fire: 0.6, works: 1.9, power: 1.4, 'pol-okg': 1.8, 'pol-iwo': 1.3, 'crp-ibd': 0.8, 'pol-bdj': 0.9 };
const paceOf = (agencyId: string) => PACE[agencyId] ?? (agencyId.startsWith('lga-') ? 2.2 : 1);

const OUTCOMES = ['Situation contained on arrival', 'Persons dispersed — area patrolled', 'Suspects handed to police', 'Victim rescued / assisted', 'Referred to investigation', 'No trace found on arrival'];
const CIVIC_DONE: Record<CategoryId, string[]> = {
  security: [],
  other: ['Checked and resolved on site'],
  fire: ['Fire put out by 2 tenders; no casualties', 'Fire contained; area made safe and handed to owner'],
  flooding: ['Drain desilted and cleared of refuse; water flowing', 'Culvert unblocked; pump deployed to clear standing water'],
  roads: ['Potholes patched with asphalt; road reopened', 'Collapsed section filled and compacted; warning signs placed'],
  waste: ['Refuse evacuated by 2 compactor trucks; site swept', 'Illegal dump cleared; notice posted'],
  infrastructure: ['Line isolated by DisCo crew and pole replaced', 'Streetlights repaired along the stretch', 'Pipe clamped and water restored'],
};

const citizens = dep.people.filter((p) => p.role === 'citizen' && p.id !== 'cit1');
const dispatchers = dep.people.filter((p) => p.role === 'dispatcher');
const METRO = dep.lgas.filter((l) => l.metro);
const OTHERS = dep.lgas.filter((l) => !l.metro);
const commanderOf = (agencyId: string) =>
  dep.people.find((p) => p.agencyId === agencyId && p.role === 'supervisor')?.id ?? dep.people.find((p) => p.agencyId === agencyId && (p.role === 'agency_head' || p.role === 'ops_manager'))?.id ?? 'cmd1';
const officersOf = (agencyId: string) => dep.people.filter((p) => p.agencyId === agencyId && p.role === 'officer').map((p) => p.id);

interface Ev {
  at: number;
  run: () => void;
}

const SHIFT_OF = (h: number): Shift => (h >= 6 && h < 14 ? 'morning' : h >= 14 && h < 22 ? 'afternoon' : 'night');

/** Duty roster at the start of the demo: most staff on the current shift. */
export function initialDuty(start: number): Record<string, DutyEntry> {
  const cur = SHIFT_OF(lagosHour(start));
  const other: Shift = cur === 'night' ? 'morning' : cur === 'morning' ? 'afternoon' : 'night';
  const duty: Record<string, DutyEntry> = {};
  for (const a of dep.agencies) {
    if (a.status === 'setting_up') continue; // not rostered yet (readiness item 3)
    const staff = dep.people.filter((p) => p.agencyId === a.id && (p.staffStatus ?? 'active') === 'active');
    staff.forEach((p, k) => {
      let on = true;
      // Waste: only Tunde's crew is out today, so new waste reports reach him.
      if (a.id === 'waste' && p.role === 'officer' && p.id !== 'wst-off1') on = false;
      // In bigger units one patrol lead is off shift.
      else if (p.role === 'officer' && !p.demo && k === staff.length - 1 && staff.filter((x) => x.role === 'officer').length >= 3) on = false;
      duty[p.id] = { on, shift: on ? cur : other };
    });
  }
  for (const p of dep.people) if (!duty[p.id] && p.role !== 'citizen' && (p.staffStatus ?? 'active') === 'active' && !p.agencyId) duty[p.id] = { on: true, shift: cur };
  return duty;
}

export function buildSeed(api: SeedApi) {
  const { start, submitAt, actAt } = api;
  let hoaxBudget = 5;
  const events: Ev[] = [];
  const later = (t: number, run: () => void) => events.push({ at: t, run });

  type Opts = { stall?: boolean; invalid?: boolean; verify?: 'yes' | 'no' | 'none'; untriaged?: boolean };

  const lifecycle = (p: { inc?: Incident }, at: number, opts: Opts = {}) => {
    const i = () => p.inc!;
    later(at + 1, () => {
      const inc = i();
      if (!inc || inc.reports[0].submittedAt !== at) return; // merged into an earlier case
      if (opts.untriaged) return;
      const pace = () => paceOf(i().agencyId);
      const ackWin = () => (i().ackDueAt - (i().t.assigned ?? i().createdAt)) / MIN;
      const resWin = () => (i().resolveDueAt - i().createdAt) / MIN;
      let t = at;

      // 1. Review (security, restricted desk, unclassified)
      if (inc.status === 'pending') {
        const sos = inc.reports[0].channel === 'sos';
        t += (inc.restricted ? between(0.6, 5) * (sos ? 0.4 : 1) : between(8, 70)) * MIN;
        if (inc.sensitiveOnly) {
          const desk = dep.people.find((x) => x.agencyId === inc.agencyId && x.role === 'sensitive')?.id ?? 'sens1';
          later(t, () => actAt(t, desk, inc.id, 'takeCase'));
        } else {
          const disp = pick(dispatchers).id;
          if (opts.invalid) {
            // v2.4: about 5 deliberate hoaxes (duty lead confirms); the rest under no-penalty reasons.
            if (hoaxBudget > 0 && inc.reports[0].identity !== 'anonymous') {
              hoaxBudget--;
              later(t, () => actAt(t, disp, inc.id, 'reject', 'Caller admitted on call-back that he made it up to test the line', 'hoax'));
              const tc = t + 4 * MIN;
              later(tc, () => actAt(tc, 'duty1', inc.id, 'confirmHoax'));
            } else {
              const [kind, why] = pick([
                ['no_trace', 'Unit found nothing at the location; caller could not be reached'],
                ['mistake', 'Caller confirmed it was a misunderstanding — good faith'],
                ['not_ours', 'Landlord–tenant dispute; advised to see the court'],
                ['duplicate', 'Same incident already handled under another case'],
              ] as const);
              later(t, () => actAt(t, disp, inc.id, 'reject', why, kind));
            }
            return;
          }
          const sev = R() < 0.15 ? pick(['critical', 'high', 'normal'] as const) : inc.severity;
          const target = inc.suggestedAgencyId ?? dep.agencies.find((a) => a.kind === 'corps' && a.lgaIds.includes(inc.lgaId))?.id ?? 'crp-ibd';
          later(t, () => actAt(t, disp, inc.id, 'verifyAndPass', { subcategory: inc.subcategory, severity: sev, toAgencyId: target, reason: 'Covers this area' }));
        }
      }

      // 2. Accept, (assign officer), work, resolve, sign off / citizen confirm
      later(t + 2, () => {
        const c = i();
        if (c.status === 'rejected') return;
        const emergency = c.restricted || c.category === 'fire';
        const desk = c.sensitiveOnly;
        let t2 = t + 2;
        let officer = c.officerId;
        if (!desk) {
          t2 += ackWin() * between(0.1, 1.15) * pace() * MIN + MIN;
          if (opts.stall && R() < 0.5) return; // never accepted — it escalates
          const tAck = t2;
          if (c.status === 'assigned' && !c.officerId) {
            // Unit handoff: commander accepts, then assigns a patrol lead.
            const cmdr = commanderOf(c.agencyId);
            const offs = officersOf(c.agencyId);
            officer = offs.length ? pick(offs) : undefined;
            later(tAck, () => actAt(tAck, cmdr, c.id, 'acceptHandoff'));
            if (officer) {
              const tAs = tAck + between(1, 4) * MIN;
              later(tAs, () => actAt(tAs, cmdr, c.id, 'passCase', { toAgencyId: c.agencyId, toPersonId: officer, reason: 'Nearest patrol' }));
              t2 = tAs + between(1, 4) * MIN;
              const tOa = t2;
              later(tOa, () => actAt(tOa, officer!, c.id, 'acceptHandoff'));
            } else officer = cmdr;
          } else {
            officer = c.officerId ?? commanderOf(c.agencyId);
            later(tAck, () => actAt(tAck, officer!, c.id, 'acceptHandoff'));
          }
          if (opts.stall) return;
        } else officer = dep.people.find((x) => x.agencyId === c.agencyId && x.role === 'sensitive')?.id ?? 'sens1';
        const who = officer!;
        t2 += (emergency ? between(1, 5) : between(20, 240) * pace()) * MIN;
        const tEn = t2;
        later(tEn, () => actAt(tEn, who, c.id, 'start'));
        if (emergency && !desk) {
          const arrive = (i().arriveDueAt ?? i().createdAt + 30 * MIN) - i().createdAt;
          const tOn = Math.max(tEn + MIN, i().createdAt + arrive * between(0.35, 1.25) * pace() + 1);
          later(tOn, () => actAt(tOn, who, c.id, 'onScene'));
          t2 = tOn + between(15, 60) * MIN;
        }
        if (c.restricted) {
          const ts = t2;
          later(ts, () => actAt(ts, who, c.id, 'addEvidence', 'note', pick(['Two patrol vehicles on scene. Area cordoned.', 'Spoke with residents; no weapons seen at this time.', 'Team canvassing the street; CCTV request sent to shop owners.', 'Victim safe and receiving first aid.'])));
          if (R() < 0.12 && !desk) {
            const tb = ts + 2 * MIN;
            later(tb, () => actAt(tb, who, c.id, 'requestBackup', 'Crowd building; need one more team'));
          }
        } else if (cat(c.category).evidence.includes('photo')) {
          const tPhoto = t2 + resWin() * between(0.15, 0.9) * pace() * MIN;
          later(tPhoto, () => actAt(tPhoto, who, c.id, 'addEvidence', 'photo', 'Before / after photographs (3)'));
          t2 = tPhoto + between(5, 40) * MIN;
        }
        const tDone = t2 + between(10, 90) * MIN;
        later(tDone, () =>
          actAt(tDone, who, c.id, 'resolve', c.restricted ? { note: pick(['Area patrolled for 2 hours; situation normal.', 'Statement taken; matter documented.', 'Team remained until crowd dispersed.']), outcome: pick(desk ? ['Victim rescued / assisted', 'Referred to investigation'] : OUTCOMES) } : { note: pick(CIVIC_DONE[c.category]) }),
        );
        if (!cat(c.category).citizenVerification) {
          // Commander sign-off
          const tSign = tDone + between(5, 50) * MIN;
          later(tSign, () => actAt(tSign, desk ? who : commanderOf(c.agencyId), c.id, 'signOff'));
        } else if (opts.verify !== 'none') {
          const tv = tDone + between(1, 20) * HOUR;
          const ans = opts.verify === 'no' ? (R() < 0.6 ? 'no' : 'partial') : 'yes';
          later(tv, () => actAt(tv, 'cit1', c.id, 'confirmFix', ans, i().reports[0].ref));
          if (ans !== 'yes') {
            const tr = tv + between(1, 4) * HOUR;
            later(tr, () => actAt(tr, who, c.id, 'acceptCase'));
            const tw = tr + between(1, 3) * HOUR;
            later(tw, () => actAt(tw, who, c.id, 'start'));
            const tp = tw + between(1, 4) * HOUR;
            later(tp, () => actAt(tp, who, c.id, 'addEvidence', 'photo', 'Photos after second visit'));
            const tf = tp + 20 * MIN;
            later(tf, () => actAt(tf, who, c.id, 'resolve', { note: 'Returned with larger crew; remaining section completed.' }));
            const tv2 = tf + between(2, 12) * HOUR;
            later(tv2, () => actAt(tv2, 'cit1', c.id, 'confirmFix', 'yes', i().reports[0].ref));
          }
        }
      });
    });
  };

  const report = (at: number, input: Omit<ReportInput, 'lgaId' | 'area'> & { lgaId?: string; area?: string }, opts?: Opts) => {
    const l = input.lgaId ? dep.lgas.find((x) => x.id === input.lgaId)! : R() < 0.68 ? pick(METRO) : pick(OTHERS);
    const area = input.area ?? pick(l.areas);
    const p: { inc?: Incident } = {};
    events.push({ at, run: () => (p.inc = submitAt(at, { ...input, text: input.text.replace(/\{a\}/g, area), lgaId: l.id, area })) });
    lifecycle(p, at, opts);
    return p;
  };

  const randomReporter = (identity: Identity) => {
    if (identity === 'anonymous') return undefined;
    const c = pick(citizens);
    return { personId: c.id, name: c.name, phone: c.phone };
  };

  // Background volume.
  for (let d = 7; d >= 0; d--) {
    const dayStart = new Date(lagosDayStart(start - d * DAY));
    const count = d === 0 ? Math.round(48 * (lagosHour(start) / 24)) : 44 + Math.floor(R() * 14);
    for (let k = 0; k < count; k++) {
      const category = weighted<Exclude<CategoryId, 'other'>>({ security: 34, flooding: d <= 3 ? 20 : 12, waste: 18, roads: 14, infrastructure: 10, fire: 6 });
      const night = category === 'security' && R() < 0.5;
      const hour = night ? pick([19, 20, 21, 22, 23, 0, 1, 2, 3]) + R() : between(6, 21.5);
      const at = dayStart.getTime() + hour * HOUR;
      if (at > start - 3 * MIN) continue;
      const sub = weighted(SUBS[category]);
      const key = `${category}/${sub === 'sos' ? 'armed' : sub}`;
      const identity: Identity = category === 'security' ? weighted({ standard: 45, confidential: 35, anonymous: 20 }) : weighted({ standard: 82, anonymous: 18 });
      const channel: Channel = category === 'security' ? weighted({ web: 25, whatsapp: 30, call_615: 30, sms: 10, ussd: 5 }) : weighted({ web: 38, whatsapp: 38, sms: 12, ussd: 6, call_615: 6 });
      let lgaId = category === 'flooding' && d <= 3 && R() < 0.5 ? 'ibn' : undefined;
      let area: string | undefined;
      // Keep the live demo locations clear so new demo reports are not merged into old ones.
      if (category === 'flooding' && lgaId === 'ibn') area = pick(['Agodi', 'Sango', 'Samonda', 'UI']);
      if (category === 'waste') {
        const l = lgaId ? dep.lgas.find((x) => x.id === lgaId)! : R() < 0.68 ? pick(METRO) : pick(OTHERS);
        lgaId = l.id;
        area = pick(l.areas.filter((a) => a !== 'Mokola')) ?? l.areas[0];
      }
      if (category === 'security' && at > start - 4 * HOUR) {
        const l = pick(dep.lgas.filter((x) => x.id !== 'ibno'));
        lgaId = l.id;
        area = pick(l.areas.filter((a) => a !== 'Agbowo')) ?? l.areas[0];
      }
      report(
        at,
        { text: pick(T[key]), category, subcategory: sub, identity, channel, reporter: randomReporter(identity), sos: sub === 'sos', lgaId, area },
        { invalid: category === 'security' && R() < 0.12, stall: category !== 'security' && R() < 0.08, verify: R() < 0.1 ? 'no' : R() < 0.08 ? 'none' : 'yes' },
      );
    }
  }

  // Apata flood cluster this morning: many residents, one master incident.
  const morning = new Date(lagosDayStart(start) + 6 * HOUR + 50 * MIN);
  const apataStart = Math.min(morning.getTime(), start - 3 * HOUR);
  for (let k = 0; k < 18; k++) {
    const at = apataStart + k * between(4, 9) * MIN;
    if (at > start - 5 * MIN) break;
    report(at, { text: pick(T['flooding/flood']), category: 'flooding', subcategory: 'flood', lgaId: 'ibsw', area: 'Apata', identity: 'standard', channel: pick(['whatsapp', 'web', 'sms']), reporter: randomReporter('standard') }, { stall: true });
  }

  // Security pattern: repeated armed/suspicious sightings around Moniya, last 48h.
  for (let k = 0; k < 7; k++) {
    const at = start - (46 - k * 6.5) * HOUR;
    report(at, { text: pick([...T['security/suspicious'], ...T['security/armed']]), category: 'security', subcategory: k % 3 === 0 ? 'armed' : 'suspicious', lgaId: 'aki', area: 'Moniya', identity: k % 2 ? 'anonymous' : 'confidential', channel: pick(['whatsapp', 'call_615', 'web']), reporter: randomReporter(k % 2 ? 'anonymous' : 'confidential') });
  }

  // The demo citizen's own reports.
  const cit = dep.people.find((p) => p.id === 'cit1')!;
  const me = { personId: cit.id, name: cit.name, phone: cit.phone };
  // Resolved by the agency, waiting for Adewale to confirm.
  const drain = report(start - 50 * HOUR, { text: 'Drainage at Bodija market road is blocked and overflowing onto the road', category: 'flooding', subcategory: 'drainage', lgaId: 'ibn', area: 'Bodija', landmark: 'Bodija market gate', identity: 'standard', channel: 'web', reporter: me }, { untriaged: true });
  const dOff = () => drain.inc!.officerId ?? commanderOf(drain.inc!.agencyId);
  later(start - 49 * HOUR, () => actAt(start - 49 * HOUR, dOff(), drain.inc!.id, 'acceptHandoff'));
  later(start - 47 * HOUR, () => actAt(start - 47 * HOUR, dOff(), drain.inc!.id, 'start'));
  later(start - 30 * HOUR, () => actAt(start - 30 * HOUR, dOff(), drain.inc!.id, 'addEvidence', 'photo', 'Drain after desilting'));
  later(start - 29 * HOUR, () => actAt(start - 29 * HOUR, dOff(), drain.inc!.id, 'resolve', { note: 'Drain desilted and cleared of refuse; water flowing' }));
  report(start - 5 * DAY, { text: 'Potholes everywhere on our street in Bodija, a car fell inside yesterday', category: 'roads', subcategory: 'local_road', lgaId: 'ibn', area: 'Bodija', landmark: 'Awolowo Avenue', identity: 'standard', channel: 'whatsapp', reporter: me }, { stall: true });
  report(start - 9 * DAY + 2 * DAY, { text: 'Streetlight not working along Bodija road for one week', category: 'infrastructure', subcategory: 'streetlight', lgaId: 'ibn', area: 'Bodija', identity: 'standard', channel: 'web', reporter: me }, { verify: 'yes' });
  report(start - 38 * MIN, { text: 'Strange men loitering around Bodija school since evening, they are watching the gate', category: 'security', subcategory: 'suspicious', lgaId: 'ibn', area: 'Bodija', landmark: 'Bodija secondary school', identity: 'confidential', channel: 'web', reporter: me }, { untriaged: true });

  // DEMO STEP 6 — armed case passed to Insp. Grace, not yet accepted. +15m escalates it.
  const armed = report(start - 25 * MIN, { text: 'Two men with guns seen around Samonda junction, they are moving towards the estate', category: 'security', subcategory: 'armed', lgaId: 'ibn', area: 'Samonda', landmark: 'Samonda filling station', identity: 'confidential', channel: 'whatsapp', reporter: randomReporter('confidential') }, { untriaged: true });
  later(start - 24 * MIN, () => actAt(start - 24 * MIN, 'disp1', armed.inc!.id, 'verifyAndPass', { subcategory: 'armed', severity: 'high', toAgencyId: 'pol-bdj', reason: 'Covers this area', note: 'Caller called back: men left on foot 10 min ago. Approach quietly.' }));
  later(start - 18 * MIN, () => actAt(start - 18 * MIN, 'cmdr1', armed.inc!.id, 'acceptHandoff'));
  later(start - 0.5 * MIN, () => actAt(start - 0.5 * MIN, 'cmdr1', armed.inc!.id, 'passCase', { toAgencyId: 'pol-bdj', toPersonId: 'pat1', reason: 'Nearest patrol', note: 'Check the estate gate and report back' }));

  // DEMO STEP 7 — accepted by Police Bodija, no officer yet. CSP Lawal passes it to Amotekun.
  const sango = report(start - 70 * MIN, { text: 'Men with guns were seen entering an uncompleted building at Sango last night, residents are afraid', category: 'security', subcategory: 'armed', lgaId: 'ibn', area: 'Sango', landmark: 'behind Sango market', identity: 'standard', channel: 'call_615', callRef: 'CALL-615-88390', reporter: randomReporter('standard') }, { untriaged: true });
  later(start - 69 * MIN, () => actAt(start - 69 * MIN, 'disp1', sango.inc!.id, 'verifyAndPass', { subcategory: 'armed', severity: 'normal', toAgencyId: 'pol-bdj', reason: 'Covers this area', note: 'Sighting from last night; no active threat reported' }));
  later(start - 55 * MIN, () => actAt(start - 55 * MIN, 'cmdr1', sango.inc!.id, 'acceptHandoff'));

  // A handoff waiting to be accepted (control room → Police Mapo).
  const mapo = report(start - 9 * MIN, { text: 'Suspicious vehicle parked near Oja Oba for 3 days, men watching houses', category: 'security', subcategory: 'suspicious', lgaId: 'ibse', area: 'Oja Oba', identity: 'anonymous', channel: 'web' }, { untriaged: true });
  later(start - 4 * MIN, () => actAt(start - 4 * MIN, pick(dispatchers).id, mapo.inc!.id, 'verifyAndPass', { subcategory: 'suspicious', severity: 'normal', toAgencyId: 'pol-map', reason: 'Covers this area' }));

  // Live control-room queue: fresh reports nobody has reviewed yet.
  report(start - 3 * MIN, { text: 'Help! Robbers are inside our compound now', category: 'security', subcategory: 'robbery', lgaId: 'egb', area: 'Olodo', identity: 'standard', channel: 'sos', sos: true, reporter: randomReporter('standard') }, { untriaged: true });
  report(start - 6 * MIN, { text: 'Gunshots heard near Ojoo motor park, people are running', category: 'security', subcategory: 'armed', lgaId: 'aki', area: 'Ojoo', identity: 'anonymous', channel: 'whatsapp' }, { untriaged: true });
  report(start - 9 * MIN, { text: 'Caller reports two groups fighting with cutlasses near the motor park. Caller is hiding in a shop.', category: 'security', subcategory: 'violence', lgaId: 'ogn', area: 'Sabo', identity: 'confidential', channel: 'call_615', callRef: 'CALL-615-88412', reporter: randomReporter('confidential') }, { untriaged: true });
  report(start - 14 * MIN, { text: 'My neighbour beats his wife every night, today she was bleeding and the children are crying', category: 'security', subcategory: 'gbv', lgaId: 'ibse', area: 'Felele', identity: 'confidential', channel: 'whatsapp', reporter: randomReporter('confidential') }, { untriaged: true });
  // A4: no keywords, no category → Unclassified, waiting for a person (not Security).
  report(start - 16 * MIN, { text: 'Something is not right near the junction by the primary school, please send someone to check', lgaId: 'ibne', area: 'Oje', identity: 'standard', channel: 'whatsapp', reporter: randomReporter('standard') }, { untriaged: true });
  report(start - 22 * MIN, { text: 'The drainage here is overflowing, water don enter road', lgaId: 'ibne', area: 'Gbagi', identity: 'standard', channel: 'whatsapp', reporter: randomReporter('standard') }, { untriaged: true });

  // v2.3: 30 days of security history clustered around Moniya, Igangan and Ojoo (Hotspots layer).
  const CLUSTERS: [string, string][] = [
    ['aki', 'Moniya'],
    ['ibno', 'Igangan'],
    ['aki', 'Ojoo'],
  ];
  for (let k = 0; k < 30; k++) {
    const [lgaId, area] = CLUSTERS[k % 3];
    const at = start - (k < 9 ? between(0.5, 6.5) : between(8, 30)) * DAY;
    const sub = pick(['armed', 'suspicious', 'robbery', 'kidnapping', 'violence']);
    report(at, { text: pick(T[`security/${sub}`]), category: 'security', subcategory: sub, lgaId, area, identity: pick(['confidential', 'anonymous'] as const), channel: pick(['call_615', 'whatsapp', 'web']), reporter: randomReporter('confidential') });
  }

  // v2.3 §3.4: a report that names a group (supervisor review before armed dispatch).
  report(start - 18 * MIN, { text: 'Fulani herders attacked our farm at night and destroyed the crops, they are still around with cutlasses', category: 'security', subcategory: 'violence', lgaId: 'ise', area: 'Ado-Awaye', identity: 'standard', channel: 'whatsapp', reporter: randomReporter('standard') }, { untriaged: true });

  // An Amotekun Ibadan case accepted by the unit with no officer yet (to assign Grace in step 23).
  const amo = report(start - 50 * MIN, { text: 'Suspicious vehicle parked near Ojoo motor park for 3 days, men watching houses', category: 'security', subcategory: 'suspicious', lgaId: 'aki', area: 'Iroko', identity: 'anonymous', channel: 'web' }, { untriaged: true });
  later(start - 48 * MIN, () => actAt(start - 48 * MIN, 'disp1', amo.inc!.id, 'verifyAndPass', { subcategory: 'suspicious', severity: 'normal', toAgencyId: 'crp-ibd', reason: 'Covers this area' }));
  later(start - 40 * MIN, () => actAt(start - 40 * MIN, 'crp1', amo.inc!.id, 'acceptHandoff'));

  // A break-glass unseal for the oversight panel to review (v2.3 §4.3).
  const gbv = report(start - 2 * HOUR, { text: 'A girl was sexually abused in Molete, the family is afraid to report', category: 'security', subcategory: 'gbv', lgaId: 'ibsw', area: 'Molete', identity: 'confidential', channel: 'whatsapp', reporter: randomReporter('confidential') }, { untriaged: true });
  later(start - 100 * MIN, () => actAt(start - 100 * MIN, 'sens1', gbv.inc!.id, 'takeCase'));
  later(start - 95 * MIN, () => actAt(start - 95 * MIN, 'sens1', gbv.inc!.id, 'breakGlass', 'Survivor asked for a call-back through the protected line'));

  // v2.4: Adewale has two confirmed reports (Trusted).
  report(start - 6 * DAY, { text: 'Burst pipe at Samonda junction, water wasting since morning', category: 'infrastructure', subcategory: 'water', lgaId: 'ibn', area: 'Samonda', identity: 'standard', channel: 'web', reporter: me }, { verify: 'yes' });

  // v2.4: Bose Akinwale — two confirmed hoaxes in 12 months (Restricted) and one pending report.
  const bose = dep.people.find((p) => p.id === 'cit-bose')!;
  const bz = { personId: bose.id, name: bose.name, phone: bose.phone };
  for (const [d, area] of [[70, 'Agodi'], [25, 'Sango']] as const) {
    const h = report(start - d * DAY, { text: `Armed robbers are attacking houses at ${area} now, come quickly`, category: 'security', subcategory: 'robbery', lgaId: 'ibn', area, identity: 'standard', channel: 'web', reporter: bz }, { untriaged: true });
    const t1 = start - d * DAY + 30 * MIN;
    later(t1, () => actAt(t1, 'disp1', h.inc!.id, 'reject', 'Unit found a quiet street; caller later admitted she wanted to test response', 'hoax'));
    const t2 = t1 + 10 * MIN;
    later(t2, () => actAt(t2, 'duty1', h.inc!.id, 'confirmHoax'));
  }
  report(start - 26 * MIN, { text: 'Suspicious men gathering behind Agodi gardens, they look like they are planning something', category: 'security', subcategory: 'suspicious', lgaId: 'ibn', area: 'Agodi', identity: 'standard', channel: 'web', reporter: bz }, { untriaged: true });

  // Events schedule further events, so keep the queue ordered by time.
  const queue = events.splice(0).sort((a, b) => a.at - b.at);
  const insert = (e: Ev) => {
    let lo = 0;
    let hi = queue.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (queue[mid].at <= e.at) lo = mid + 1;
      else hi = mid;
    }
    queue.splice(lo, 0, e);
  };
  while (queue.length) {
    const e = queue.shift()!;
    if (e.at > start) continue;
    e.run();
    for (const n of events.splice(0)) insert(n);
  }
}

const cat = (id: CategoryId) => dep.categories.find((c) => c.id === id)!;

// ---------- Station chat history (PRD v2.2 §4.5) ----------

type ChatInput = { kind: 'text' | 'photo' | 'voice' | 'location' | 'case'; text?: string; photo?: string; caseId?: string; urgent?: boolean; pinned?: boolean };
export interface ChatSeedApi {
  start: number;
  post: (at: number, personId: string, stationId: string, v: ChatInput) => unknown;
  system: (stationId: string, text: string, at: number) => void;
  broadcast: (at: number, personId: string, text: string, lgaIds: string[], ackedBy: string[]) => void;
  transfer: (at: number, personId: string, toStationId: string, byId: string, reason: string) => void;
}

/** A small, static photo (no canvas needed while seeding). */
const CHECKPOINT_PHOTO =
  'data:image/svg+xml;utf8,' +
  encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" width="480" height="320"><rect width="480" height="320" fill="#cfe0ea"/><rect y="200" width="480" height="120" fill="#9c8f7a"/><rect x="60" y="120" width="140" height="80" fill="#2d4a7a"/><rect x="240" y="150" width="200" height="12" fill="#e11d48"/><rect x="240" y="170" width="200" height="12" fill="#fff"/><rect y="286" width="480" height="34" fill="rgba(0,0,0,.55)"/><text x="12" y="309" fill="#fff" font-family="sans-serif" font-size="16">Checkpoint, Bodija market road</text></svg>',
  );

export function seedChat(api: ChatSeedApi) {
  const { start, post, broadcast, transfer } = api;
  const h = (x: number) => start - x * HOUR;
  const bdjOfficers = dep.people.filter((p) => p.agencyId === 'pol-bdj' && p.role === 'officer' && p.id !== 'pat1' && p.id !== 'bayo').map((p) => p.id);
  const crpOfficers = dep.people.filter((p) => p.agencyId === 'crp-ibd' && p.role === 'officer').map((p) => p.id);
  const [b1, b2] = bdjOfficers;
  const [a1, a2] = crpOfficers;

  // Police Bodija
  post(h(46), 'cmdr1', 'pol-bdj', { kind: 'text', text: 'Good morning team. Two patrol teams on Bodija and Agodi today, one at the UI gate. Report every 2 hours.' });
  post(h(45.8), 'pat1', 'pol-bdj', { kind: 'text', text: 'Copied sir. Team A moving to Bodija market road.' });
  post(h(30), b1, 'pol-bdj', { kind: 'photo', text: 'Checkpoint set at Bodija market road', photo: CHECKPOINT_PHOTO });
  post(h(29.5), 'cmdr1', 'pol-bdj', { kind: 'text', text: '@Grace please check on the shop owners near the market gate before 6pm.' });
  post(h(6), 'pat1', 'pol-bdj', { kind: 'text', text: 'Market road quiet now. Moving to Agodi roundabout.' });
  post(h(3), 'cmdr1', 'pol-bdj', {
    kind: 'text',
    text: 'Shift briefing (today): Team A Bodija/Samonda, Team B Agodi/UI. Watch for the white Sienna reported near Ojoo. DPO desk line 0803 123 4521 for anything urgent.',
  });
  post(h(2.5), b2, 'pol-bdj', { kind: 'text', text: 'Received. Fuel collected for both vehicles.' });

  // Amotekun Ibadan
  post(h(47), 'crp1', 'crp-ibd', { kind: 'text', text: 'Night patrol rota for this week: Moniya/Ojoo axis 8pm–2am, Akinyele farm roads 2am–6am. Radio check every hour.', pinned: true });
  post(h(46.5), a1, 'crp-ibd', { kind: 'text', text: 'Received, Commander.' });
  post(h(26), a2, 'crp-ibd', { kind: 'voice', text: 'Voice note 0:18' });
  post(h(10), a1, 'crp-ibd', { kind: 'location', text: 'Ojoo motor park, Akinyele' });
  post(h(2), 'crp1', 'crp-ibd', { kind: 'text', text: 'Stay alert at Moniya — repeated sightings of the same men this week.' });

  // Control-room broadcast to the stations covering Akinyele and Ibadan North.
  broadcast(h(5), 'duty1', 'BOLO: grey Toyota Corolla, no plates, 3 men, last seen Moniya heading Ojoo. Report sightings to 615.', ['aki', 'ibn'], ['crp1']);

  // A transfer waiting for Comdr. Adegoke.
  const mover = dep.people.find((p) => p.agencyId === 'crp-oyo' && p.role === 'officer');
  const sender = dep.people.find((p) => p.agencyId === 'crp-oyo' && p.role === 'supervisor');
  if (mover && sender) transfer(start - 12 * MIN, mover.id, 'crp-ibd', sender.id, 'Redeployment');
}

export function seedCaseCards(api: ChatSeedApi, incidents: Incident[]) {
  const closed = incidents.find((i) => i.agencyId === 'pol-bdj' && i.status === 'closed');
  const amo = incidents.find((i) => i.agencyId === 'crp-ibd' && i.status !== 'pending');
  if (closed) api.post(api.start - 29 * HOUR, 'cmdr1', 'pol-bdj', { kind: 'case', caseId: closed.id });
  if (amo) api.post(api.start - 20 * HOUR, 'crp1', 'crp-ibd', { kind: 'case', caseId: amo.id });
}

// ---------- v2.3 seed: conduct feedback and past officer SOS ----------

export interface V23SeedApi {
  start: number;
  feedback: (at: number, i: Incident, money: boolean, respect: 'yes' | 'somewhat' | 'no', speed?: number, text?: string) => void;
  sos: (at: number, officerId: string, kind: 'distress' | 'missed', closeAfterMin: number, goingAgency?: string) => Incident;
  [k: string]: unknown;
}

export function seedV23(api: V23SeedApi, incidents: Incident[]) {
  const { start, feedback, sos } = api;
  const closed = incidents.filter((i) => i.status === 'closed' && i.t.closed && !i.officerSos);
  // Three complaints: one "asked for money" against a Police Iyaganku case, two "not respected".
  const money = closed.find((i) => i.agencyId === 'pol-iyg');
  const respect = closed.filter((i) => i !== money && ['pol-map', 'crp-ogb', 'pol-iwo', 'lga-egb'].includes(i.agencyId)).slice(0, 2);
  const special = new Set([money, ...respect].filter(Boolean) as Incident[]);
  if (money) feedback(money.t.closed! + 3 * HOUR, money, true, 'somewhat', 2, 'The officer said we should bring something for fuel before they would come.');
  for (const i of respect) feedback(i.t.closed! + 5 * HOUR, i, false, 'no', 2, 'They shouted at my father and called him a liar.');
  for (const i of closed) {
    if (special.has(i) || R() > 0.6) continue;
    const x = R();
    feedback(i.t.closed! + between(1, 20) * HOUR, i, false, x < 0.86 ? 'yes' : 'somewhat', 3 + Math.floor(R() * 3));
  }
  // Two past officer SOS alerts for the Officer safety report.
  const iwo = dep.people.find((p) => p.agencyId === 'pol-iwo' && p.role === 'officer');
  const amo = dep.people.find((p) => p.agencyId === 'crp-ibd' && p.role === 'officer');
  if (iwo) sos(start - 5 * DAY - 3 * HOUR, iwo.id, 'distress', 38, 'pol-iwo');
  if (amo) sos(start - 2 * DAY - 7 * HOUR, amo.id, 'missed', 24, 'crp-ibd');
}
